; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Print "VB test 3"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; 22: Chk Red, 0
			dc.l p_chk_c, lit_0, lit_0

			; 23: Chk Green, 5
			dc.l p_chk_c, lit_5, lit_5

			; 24: Chk Blue, 6
			dc.l p_chk_c, lit_6, lit_6

			; 25: Chk Colour.Blue + Size.Large, 16
			dc.l p_chk_c, lit_16, lit_16

			; 26: c = Green
			dc.l kw_ltov, 5, var_c

			; 27: Chk c, 5
			dc.l p_chk_c, var_c, lit_5

			; 29: .w = 3
			dc.l kw_ltov, 3, var_b_w

			; 30: .h = 4
			dc.l kw_ltov, 4, var_b_h

			; 31: .label = "box"
			dc.l kw_strcpy, var_b_label, str1

			; 32: n = .w * .h
			dc.l kw_mulvv, var_b_w, var_b_h, var_n

			; 34: Chk n, 12
			dc.l p_chk_c, var_n, lit_12

			; 35: ChkS b.label, "box"
			dc.l p_chks_c, var_b_label, str1

			; 36: For i = 0 To 2
			dc.l kw_ztov, var_i
for1_t:

			; 38: .w = i
			dc.l kw_aset, arr_boxes_w, var_i, var_i

			; 39: .h = i * 2
			dc.l kw_2x, var_i, tmp1
			dc.l kw_aset, arr_boxes_h, var_i, tmp1

			; 41: Next
			dc.l kw_next1l, var_i, 2, for1_t
for1_e:

			; 42: Chk boxes(2).w + boxes(2).h, 6
			dc.l kw_add, arr_boxes_w+4, arr_boxes_h+4, tmp0
			dc.l p_chk_c, tmp0, lit_6

			; 43: n = 0
			dc.l kw_ztov, var_n

			; 44: For i = 1 To 3
			dc.l kw_ltov, 1, var_i
for2_t:

			; 45: On i GoSub one, two, three
			dc.l kw_cpeqvl, var_i, 1
			dc.l kw_goto_iffalse, on3_0
			dc.l lbl_one_gs
			dc.l on3_e_go
on3_0:
			dc.l kw_cpeqvl, var_i, 2
			dc.l kw_goto_iffalse, on3_1
			dc.l lbl_two_gs
			dc.l on3_e_go
on3_1:
			dc.l kw_cpeqvl, var_i, 3
			dc.l kw_goto_iffalse, on3_2
			dc.l lbl_three_gs
on3_2:
on3_e:

			; 46: Next
			dc.l kw_next1l, var_i, 3, for2_t
for2_e:

			; 47: Chk n, 321
			dc.l p_chk_c, var_n, lit_321

			; 48: i = 2
			dc.l kw_ltov, 2, var_i

			; 49: On i GoTo l1, l2
			dc.l kw_cpeqvl, var_i, 1
			dc.l kw_goto_iftrue, lbl_l1
			dc.l kw_cpeqvl, var_i, 2
			dc.l kw_goto_iftrue, lbl_l2

			; 50: Chk 0, 1
			dc.l p_chk_c, lit_0, lit_1

			; 51: l1:
lbl_l1:

			; 52: Chk 0, 1
			dc.l p_chk_c, lit_0, lit_1

			; 53: l2:
lbl_l2:

			; 54: Chk 1, 1
			dc.l p_chk_c, lit_1, lit_1

			; 55: k = Inkey$
			dc.l kw_inkeys, stmp0
			dc.l kw_strcpy, var_k, stmp0

			; 56: ChkS k, ""
			dc.l p_chks_c, var_k, str2

			; 57: Print
			dc.l kw_printnl

			; 58: Print t; " tests, "; bad; " failed"
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str3
			dc.l kw_printint, var_bad
			dc.l kw_printstrvar, str4
			dc.l kw_printnl

			; 59: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str5
			dc.l kw_waitkey
			dc.l kw_stop

			; 60: one:
lbl_one:

			; 61: n = n + 1
			dc.l kw_inc, var_n

			; 62: Return
			dc.l lbl_one_rt

			; 63: two:
lbl_two:

			; 64: n = n + 20
			dc.l kw_addl, var_n, 20, var_n

			; 65: Return
			dc.l lbl_two_rt

			; 66: three:
lbl_three:

			; 67: n = n + 300
			dc.l kw_addl, var_n, 300, var_n

			; 68: Return
			dc.l lbl_three_rt

; ============================================================
; sub chk (turbo mode)
; ============================================================

p_chk:

			; 71: t = t + 1
			dc.l kw_inc, var_t

			; 72: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str6

			; 73: If got = want Then Print "ok "; Else Print "FAIL("; got; ") "; : bad = bad + 1
			dc.l kw_cpeqvv, var_chk_got, var_chk_want
			dc.l kw_goto_iffalse, if5_1
			dc.l kw_printstrvar, str7
			dc.l if5_e_go
if5_1:
			dc.l kw_printstrvar, str8
			dc.l kw_printint, var_chk_got
			dc.l kw_printstrvar, str9
			dc.l kw_inc, var_bad
if5_e:
			dc.l p_chk_r

; ============================================================
; sub chks (turbo mode)
; ============================================================

p_chks:

			; 77: t = t + 1
			dc.l kw_inc, var_t

			; 78: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str6

			; 79: If got = want Then Print "ok "; Else Print "FAIL["; got; "] "; : bad = bad + 1
			dc.l kw_strcmpeq, var_chks_got, var_chks_want
			dc.l kw_goto_iffalse, if6_1
			dc.l kw_printstrvar, str7
			dc.l if6_e_go
if6_1:
			dc.l kw_printstrvar, str10
			dc.l kw_printstrvar, var_chks_got
			dc.l kw_printstrvar, str11
			dc.l kw_inc, var_bad
if6_e:
			dc.l p_chks_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

on3_e_go:			lea on3_e, sp
			rts
if5_e_go:			lea if5_e, sp
			rts
if6_e_go:			lea if6_e, sp
			rts
lbl_one_gs:			move.l sp, lbl_one_rs
			lea lbl_one, sp
			rts
lbl_one_rt:			movea.l lbl_one_rs, sp
			rts
lbl_two_gs:			move.l sp, lbl_two_rs
			lea lbl_two, sp
			rts
lbl_two_rt:			movea.l lbl_two_rs, sp
			rts
lbl_three_gs:			move.l sp, lbl_three_rs
			lea lbl_three, sp
			rts
lbl_three_rt:			movea.l lbl_three_rs, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_chks_c:		; call chks
			movea.l (sp)+, a0		; got
			lea var_chks_got, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si0_e
p_chks_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si0
			beq p_chks_si0_z
p_chks_si0_e:
			clr.b (a1)
p_chks_si0_z:
			movea.l (sp)+, a0		; want
			lea var_chks_want, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si1_e
p_chks_si1:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si1
			beq p_chks_si1_z
p_chks_si1_e:
			clr.b (a1)
p_chks_si1_z:
			move.l sp, p_chks_rs
			lea p_chks, sp
			rts
p_chks_r:		; end of chks
			movea.l p_chks_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
lit_0:			dc.w 0
lit_5:			dc.w 5
lit_6:			dc.w 6
lit_16:			dc.w 16
lit_12:			dc.w 12
lit_321:			dc.w 321
lit_1:			dc.w 1

; ============================================================
; Strings
; ============================================================

str0:			dc.b "VB test 3", 0
str1:			dc.b "box", 0
str2:			dc.b 0
str3:			dc.b " tests, ", 0
str4:			dc.b " failed", 0
str5:			dc.b "Press a key", 0
str6:			dc.b ":", 0
str7:			dc.b "ok ", 0
str8:			dc.b "FAIL(", 0
str9:			dc.b ") ", 0
str10:			dc.b "FAIL[", 0
str11:			dc.b "] ", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_2x
kw_2x:
			movea.l (sp)+, a0
			move.w (a0), d0
			add.w d0, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			move.b d0, (a2)+
			beq kw_iks_e
			clr.b (a2)
kw_iks_e:
			rts

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_c:			dc.w 0
var_b_w:			dc.w 0
var_b_h:			dc.w 0
			dc.b 40			; capacity
var_b_label:			ds.b 41
			even
var_n:			dc.w 0
var_i:			dc.w 0
			dc.b 40			; capacity
var_k:			ds.b 41
			even
var_t:			dc.w 0
var_bad:			dc.w 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
p_chks_rs:			dc.l 0
			dc.b 40			; capacity
var_chks_got:			ds.b 41
			even
			dc.b 40			; capacity
var_chks_want:			ds.b 41
			even
lbl_one_rs:			dc.l 0
lbl_two_rs:			dc.l 0
lbl_three_rs:			dc.l 0
tmp0:			dc.w 0
tmp1:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_boxes		equ ntc_bss + 0		; 6 bytes
arr_boxes_w		equ ntc_bss + 6		; 6 bytes
arr_boxes_h		equ ntc_bss + 12		; 6 bytes
ntc_bss_size	equ 18
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
